count = 0
for pat, repl in replacements:
    content, num = re.subn(pat, repl, content, flags=re.MULTILINE)
    count += num

with open('istqb-ct-ut-complete-guide.md', 'w', encoding='utf-8') as f:
    f.write(content)

print(f"Replaced {count} instances.")

# Make sure no untagged code block is remaining
untagged = re.findall(r'^```$', content, flags=re.MULTILINE)
print(f"Remaining untagged code blocks: {len(untagged) // 2}")
